-- commitment transaction functions

create or replace function private.upsert_finance_commitment(p_commitment_id text,p_name text,p_category text,p_total numeric,p_due_date date default null,p_note text default '') returns private.finance_commitments language plpgsql security definer set search_path='' as $$ declare v private.finance_commitments; begin if not private.has_panorama_finanzas_access() then raise exception 'Acceso no autorizado' using errcode='42501'; end if; if trim(coalesce(p_name,''))='' or p_total<=0 then raise exception 'Compromiso inválido'; end if; insert into private.finance_commitments(id,name,category,total,due_date,note) values(p_commitment_id,trim(p_name),coalesce(nullif(trim(p_category),''),'otro_compromiso'),p_total,p_due_date,coalesce(p_note,'')) on conflict(id) do update set name=excluded.name,category=excluded.category,total=excluded.total,due_date=excluded.due_date,note=excluded.note,updated_at=now() returning * into v; if v.paid_amount>v.total then raise exception 'El total no puede ser menor que lo ya pagado'; end if; return v; end $$;
create or replace function public.upsert_finance_commitment(p_commitment_id text,p_name text,p_category text,p_total numeric,p_due_date date default null,p_note text default '') returns private.finance_commitments language sql security invoker set search_path='' as $$ select * from private.upsert_finance_commitment($1,$2,$3,$4,$5,$6); $$;